<template><main class="zj-workspace"><header class="zj-heading"><div><div class="zj-eyebrow">众基消防 / 合作网络</div><h1>中间人管理</h1><p>集中维护联系信息，关联每一份合作合同。</p></div><el-button type="primary" icon="Plus" @click="edit()" v-hasPermi="['management:intermediary:edit']">添加中间人</el-button></header><section class="zj-card"><div class="zj-filters"><el-input v-model="query.name" placeholder="搜索中间人姓名" aria-label="中间人姓名" clearable @keyup.enter="search"/><el-button type="primary" icon="Search" @click="search">查询</el-button><el-button @click="query.name='';search()">清空</el-button><el-button icon="Refresh" aria-label="刷新" @click="load"/></div></section><section class="zj-card"><el-alert v-if="error" title="加载失败，请刷新重试" type="error" :closable="false"/><el-table v-loading="loading" :data="rows" empty-text="尚无中间人，可以添加第一位合作伙伴"><el-table-column label="姓名" min-width="150"><template #default="{row}"><strong>{{row.name}}</strong></template></el-table-column><el-table-column prop="phone" label="电话" min-width="160"/><el-table-column prop="company" label="公司 / 单位" min-width="200" show-overflow-tooltip/><el-table-column prop="email" label="邮箱" min-width="200"/><el-table-column prop="remark" label="备注" min-width="180" show-overflow-tooltip/><el-table-column label="操作" width="140" fixed="right"><template #default="{row}"><el-button link type="primary" @click="edit(row)" v-hasPermi="['management:intermediary:edit']">编辑</el-button><el-button link type="danger" @click="remove(row)" v-hasPermi="['management:intermediary:edit']">删除</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="query.pageNum" v-model:page-size="query.pageSize" :total="total" layout="total, prev, pager, next" @current-change="load"/></section>
<el-drawer v-model="open" :title="form.id?'编辑中间人':'添加中间人'" size="min(560px, 96vw)" class="zj-drawer" :before-close="beforeClose" :close-on-click-modal="false"><el-form ref="formRef" :model="form" label-position="top" :rules="rules" :disabled="saving"><h3>联系信息</h3><el-form-item label="姓名" prop="name"><el-input v-model="form.name" maxlength="100"/></el-form-item><el-form-item label="电话"><el-input v-model="form.phone" maxlength="50"/></el-form-item><el-form-item label="公司 / 单位"><el-input v-model="form.company" maxlength="200"/></el-form-item><el-form-item label="邮箱" prop="email"><el-input v-model="form.email" maxlength="200"/></el-form-item><el-form-item label="备注"><el-input v-model="form.remark" type="textarea" :rows="5" maxlength="2000" show-word-limit/></el-form-item></el-form><template #footer><el-button @click="beforeClose(()=>open=false)">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存中间人</el-button></template></el-drawer></main></template>
<script setup name="ZhongjiIntermediary">
import {intermediaries,saveIntermediary,removeIntermediary} from '@/api/zhongji';import '@/assets/styles/zhongji.scss';
const {proxy}=getCurrentInstance();const rows=ref([]),total=ref(0),loading=ref(false),error=ref(false),open=ref(false),saving=ref(false),form=ref({}),formRef=ref();const query=reactive({name:'',pageNum:1,pageSize:20});let snapshot='',sequence=0;const rules={name:[{required:true,message:'请填写姓名',trigger:'blur'}],email:[{type:'email',message:'邮箱格式不正确',trigger:'blur'}]};
async function load(){const n=++sequence;loading.value=true;error.value=false;try{const r=await intermediaries({...query});if(n===sequence){rows.value=r.rows;total.value=r.total;}}catch{if(n===sequence){rows.value=[];error.value=true;}}finally{if(n===sequence)loading.value=false;}}function search(){query.pageNum=1;load();}
function edit(row){form.value=row?{...row}:{name:'',phone:'',company:'',email:'',remark:''};snapshot=JSON.stringify(form.value);open.value=true;}
async function beforeClose(done){if(saving.value)return;if(JSON.stringify(form.value)!==snapshot){try{await proxy.$modal.confirm('有未保存的修改，确认放弃？');}catch{return;}}done();}
async function save(){if(!await formRef.value.validate().catch(()=>false))return;saving.value=true;try{await saveIntermediary(form.value);open.value=false;proxy.$modal.msgSuccess('已保存');load();}finally{saving.value=false;}}
async function remove(row){await proxy.$modal.confirm(`删除中间人“${row.name}”？已被合同引用的中间人不能删除。`);await removeIntermediary(row.id);proxy.$modal.msgSuccess('已删除');load();}onMounted(load);
</script>
